"""Reading results for reporting, with the provenance line every generated file carries."""

from __future__ import annotations

import csv
from dataclasses import dataclass
from pathlib import Path
from typing import Any

from declarative_iac.core.canonical import read_json
from declarative_iac.core.hashing import sha256_file
from declarative_iac.core.paths import relative, results_dir


class MissingResult(FileNotFoundError):
    """A report input has not been produced yet."""


@dataclass(frozen=True)
class Source:
    """One results directory: its files and the hash of its manifest."""

    directory: Path

    @classmethod
    def static(cls, experiment: str, snapshot: str = "B1") -> Source:
        return cls(results_dir() / "static" / experiment / snapshot)

    def path(self, name: str) -> Path:
        path = self.directory / name
        if not path.is_file():
            raise MissingResult(relative(path))
        return path

    def json(self, name: str = "summary.json") -> Any:
        return read_json(self.path(name))

    def csv(self, name: str) -> list[dict[str, str]]:
        with self.path(name).open(newline="", encoding="utf-8") as handle:
            return list(csv.DictReader(handle))

    @property
    def manifest_sha256(self) -> str:
        return sha256_file(self.path("manifest.json"))

    def cite(self) -> str:
        return f"{relative(self.directory)} (manifest sha256 {self.manifest_sha256[:12]})"


def header(sources: list[Source], comment: str = "<!-- {} -->") -> str:
    """The provenance line at the top of a generated file."""

    cited = "; ".join(s.cite() for s in sources)
    return comment.format(f"Generated by `declarative-iac report` from {cited}. Do not edit.")
